#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b;
    if (!(cin >> a >> b)) return 0;

    // Generate all numbers with exactly one zero in binary representation
    // up to 1e18 and count those in [a, b].
    const long long LIMIT = 1000000000000000000LL;
    long long ans = 0;

    // For bit length L (number of bits), we consider positions of the single zero.
    // L ranges so that the maximum value is <= 1e18.
    // 2^60 ~ 1e18, so L up to about 60 is enough.
    for (int L = 2; L <= 60; ++L) {
        // All bits 1: value = (1LL << L) - 1
        long long allOnes = (1LL << L) - 1;
        for (int zeroPos = 0; zeroPos < L; ++zeroPos) {
            // zeroPos: 0 is least significant bit, L-1 is most significant bit
            long long val = allOnes & ~(1LL << zeroPos);
            if (val > LIMIT) continue;
            if (val >= a && val <= b) ++ans;
        }
    }

    cout << ans << '\n';
    return 0;
}

