int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b;
    if (!(cin >> a >> b)) return 0;

    // Precompute all numbers with exactly one zero in binary (no leading zeros)
    // up to 1e18.
    vector<long long> nums;
    const long long LIMIT = 1000000000000000000LL;

    // For bit length L (number of bits), highest bit is 1.
    // We need exactly one zero among the remaining L-1 bits.
    // So choose position of zero among positions 0..L-2 (0 = least significant).
    for (int L = 2; ; ++L) {
        // Highest value for this length is (1<<L)-1, but we must stay within LIMIT.
        // If minimal value with this length exceeds LIMIT, break.
        // Minimal value with length L and one zero is when zero is at some position,
        // but still >= (1<<(L-1)).
        if ((1LL << (L-1)) > LIMIT) break;

        for (int zeroPos = 0; zeroPos <= L - 2; ++zeroPos) {
            long long x = 0;
            // Set highest bit
            x |= (1LL << (L - 1));
            // Set all lower bits to 1
            x |= ((1LL << (L - 1)) - 1);
            // Clear the chosen zero position
            x &= ~(1LL << zeroPos);

            if (x <= LIMIT) nums.push_back(x);
        }
    }

    sort(nums.begin(), nums.end());
    nums.erase(unique(nums.begin(), nums.end()), nums.end());

    auto cnt = [&](long long x) {
        return (long long)(upper_bound(nums.begin(), nums.end(), x) - nums.begin());
    };

    long long ans = cnt(b) - cnt(a - 1);
    cout << ans << '\n';

    return 0;
}

