    // Generate all numbers with exactly one zero in binary representation
    // Form: all bits 1 except exactly one bit 0, no leading zeros.
    // Let length = number of bits, zero position z (0-based from LSB).
    for (int len = 2; len <= 60; ++len) { // 2..60 bits enough for < 2^60 ~ 1e18
        long long allOnes = (1LL << len) - 1;
        for (int z = 0; z < len; ++z) {
            long long x = allOnes - (1LL << z); // clear bit z
            if (x > LIMIT) continue;
            nums.push_back(x);
        }
    }

    sort(nums.begin(), nums.end());
    nums.erase(unique(nums.begin(), nums.end()), nums.end());

    auto itL = lower_bound(nums.begin(), nums.end(), a);
    auto itR = upper_bound(nums.begin(), nums.end(), b);
    cout << (itR - itL) << '\n';

    return 0;
}

