            long long x = 0;
            for (int i = 0; i < L; ++i) {
                if (i == z) continue; // zero bit
                x |= (1LL << i);
            }
            if (x > LIMIT) continue;
            nums.push_back(x);
        }
    }

    sort(nums.begin(), nums.end());
    nums.erase(unique(nums.begin(), nums.end()), nums.end());

    auto it1 = lower_bound(nums.begin(), nums.end(), a);
    auto it2 = upper_bound(nums.begin(), nums.end(), b);
    cout << (it2 - it1) << '\n';

    return 0;
}

