int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b;
    if (!(cin >> a >> b)) return 0;

    // Generate all numbers with exactly one zero in binary representation
    // up to 1e18, then count those in [a, b].
    const long long LIMIT = 1000000000000000000LL;
    vector<long long> nums;

    // For bit-length L (number of bits), we place exactly one '0'
    // and all other bits are '1'. Leading bit must be 1, so zero position
    // can be from 0 to L-2 (0-based from LSB).
    for (int L = 2; L <= 60; ++L) { // 2 bits minimum (can't have exactly one zero with 1 bit)
        long long full = (1LL << L) - 1; // all ones
        for (int z = 0; z <= L - 2; ++z) {
            long long x = full ^ (1LL << z); // flip one bit to zero
            if (x > LIMIT) continue;
            nums.push_back(x);
        }
    }

    sort(nums.begin(), nums.end());
    nums.erase(unique(nums.begin(), nums.end()), nums.end());

    auto it1 = lower_bound(nums.begin(), nums.end(), a);
    auto it2 = upper_bound(nums.begin(), nums.end(), b);
    cout << (it2 - it1) << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

long long countUpTo(long long x) {
    if (x <= 0) return 0;
    long long cnt = 0;
    for (int len = 2; len <= 60; ++len) {
        for (int zeroPos = 1; zeroPos < len - 1; ++zeroPos) {
            long long n = (1LL << len) - 1 - (1LL << zeroPos);
            if (n > x) continue;
            cnt++;
        }
    }
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long a, b;
    if (!(cin >> a >> b)) return 0;
    cout << countUpTo(b) - countUpTo(a - 1) << '\n';
    return 0;
}
